int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    int K;
    if (!(cin >> s >> K)) return 0;

    int n = (int)s.size();
    int keep = n - K;

    string ans;
    ans.reserve(keep);

    vector<char> st;
    st.reserve(n);

    for (char c : s) {
        while (!st.empty() && K > 0 && st.back() < c) {
            st.pop_back();
            --K;
        }
        st.push_back(c);
    }

    while (K > 0) {
        st.pop_back();
        --K;
    }

    for (int i = 0; i < keep; ++i) ans += st[i];
    cout << ans << '\n';
    return 0;
}

